import java.util.*;
public final class RotateListTest {
    static RotateList.ListNode[] nodes(int...v){RotateList.ListNode[] a=new RotateList.ListNode[v.length];for(int i=0;i<v.length;i++){a[i]=new RotateList.ListNode(v[i]);if(i>0)a[i-1].next=a[i];}return a;}
    static void check(int[] vals,int k,int[] expected){RotateList.ListNode[] a=nodes(vals);RotateList.ListNode h=a.length==0?null:a[0];RotateList.ListNode r=RotateList.rotateRight(h,k);List<RotateList.ListNode> seen=new ArrayList<>();for(RotateList.ListNode p=r;p!=null;p=p.next){if(seen.contains(p))throw new AssertionError("cycle");seen.add(p);if(seen.size()>a.length)throw new AssertionError("too many");}if(seen.size()!=a.length)throw new AssertionError("lost node");for(RotateList.ListNode x:a)if(!seen.contains(x))throw new AssertionError("identity lost");int[] got=seen.stream().mapToInt(x->x.val).toArray();if(!Arrays.equals(got,expected))throw new AssertionError(Arrays.toString(got));}
    public static void main(String[]x){check(new int[]{},0,new int[]{});check(new int[]{1},999,new int[]{1});check(new int[]{1,2,3,4,5},2,new int[]{4,5,1,2,3});check(new int[]{0,1,2},4,new int[]{2,0,1});check(new int[]{1,2,3},3,new int[]{1,2,3});check(new int[]{1,2},Integer.MAX_VALUE,new int[]{2,1});boolean threw=false;try{RotateList.rotateRight(nodes(1,2)[0],-1);}catch(IllegalArgumentException e){threw=true;}if(!threw)throw new AssertionError("negative");System.out.println("PASS empty singleton sample modulo full-cycle huge-k identity no-cycle negative-contract exact-fence");}
}
